using System;using System.IO;using System.Xml;using System.Collections.Generic;
public static class BatchThreeCartPrefabs {
 public static string Run(){string folder=Path.Combine(GameIO.GetUserGameDataDir(),"BatchTwoTools");var pairs=new Dictionary<string,string>();var doc=new XmlDocument();foreach(string file in new[]{"forest-art-report.xml","arbor-art-report.xml","dungeon-art-report.xml"}){doc.Load(Path.Combine(folder,file));foreach(XmlElement e in doc.SelectNodes("/*/prefab"))pairs[e.GetAttribute("target")]=e.GetAttribute("source");}foreach(string n in new[]{"delve_forest_cabin_01_garden","delve_forest_cabin_04_garden","delve_forest_farm_12_garden"})pairs[n]=pairs[n.Replace("_garden","")];var report=new XmlDocument();report.LoadXml("<cartPrefabs/>");int total=0;
 foreach(var pair in pairs){var native=new Prefab();var p=new Prefab();if(!native.Load(pair.Value,true,true,false,false)||!p.Load(pair.Key,true,true,false,false))throw new Exception("Prefab missing "+pair.Key);var row=report.CreateElement("prefab");row.SetAttribute("name",pair.Key);report.DocumentElement.AppendChild(row);int changes=0;
 for(int y=0;y<native.size.y;y++)for(int z=0;z<native.size.z;z++)for(int x=0;x<native.size.x;x++){var b=native.GetBlock(x,y,z);if(b.ischild||!b.Block.GetBlockName().StartsWith("cntShoppingCart"))continue;total++;var before=p.GetBlock(x,y,z);if(before.rawData==b.rawData)continue;if(before.Block.isMultiBlock)throw new Exception("Cart replaced by multiblock "+pair.Key);var e=report.CreateElement("cell");e.SetAttribute("x",x.ToString());e.SetAttribute("y",y.ToString());e.SetAttribute("z",z.ToString());e.SetAttribute("before",before.Block.GetBlockName());e.SetAttribute("after",b.Block.GetBlockName());row.AppendChild(e);p.SetBlock(x,y,z,b);p.SetDensity(x,y,z,127);changes++;}
 if(changes>0){var loc=p.location;string xml=File.ReadAllText(loc.FullPathNoExtension+".xml");if(!p.Save(loc,true))throw new Exception("Save "+pair.Key);File.WriteAllText(loc.FullPathNoExtension+".xml",xml);}}
 report.Save(Path.Combine(GameIO.GetUserGameDataDir(),"BatchThreeTools/cart-prefabs.xml"));return "PASS "+pairs.Count+" prefab audits; "+total+" original cart locations retained";}
}
